-- Respaldo previo a la migración 002; generado en modo de solo lectura.

SET client_encoding = 'UTF8';

BEGIN;

CREATE TABLE IF NOT EXISTS public."simulacion_corrida" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "fecha_hora" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "escenario" text NOT NULL,
    "parametros_usados" jsonb NOT NULL,
    "etiqueta" text DEFAULT 'NO_CALIBRADO'::text NOT NULL,
    "es_supuesto" boolean DEFAULT true NOT NULL,
    "fuente" text NOT NULL,
    CONSTRAINT "simulacion_corrida_pkey" PRIMARY KEY (id),
    CONSTRAINT "simulacion_corrida_etiqueta_check" CHECK (etiqueta = 'NO_CALIBRADO'::text)
);

CREATE TABLE IF NOT EXISTS public."simulacion_resultado" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "id_corrida" bigint NOT NULL,
    "id_pecera" integer NOT NULL,
    "id_especie" integer NOT NULL,
    "horas_fuera_rango" numeric(12,4) NOT NULL,
    "factor_dominante" text,
    "mortalidad_p5_pct" numeric(7,4) NOT NULL,
    "mortalidad_mediana_pct" numeric(7,4) NOT NULL,
    "mortalidad_p95_pct" numeric(7,4) NOT NULL,
    "etiqueta" text DEFAULT 'NO_CALIBRADO'::text NOT NULL,
    "es_supuesto" boolean DEFAULT true NOT NULL,
    "fuente" text NOT NULL,
    CONSTRAINT "simulacion_resultado_pkey" PRIMARY KEY (id),
    CONSTRAINT "uq_simulacion_resultado" UNIQUE (id_corrida, id_pecera, id_especie),
    CONSTRAINT "simulacion_resultado_id_corrida_fkey" FOREIGN KEY (id_corrida) REFERENCES simulacion_corrida(id) ON DELETE CASCADE,
    CONSTRAINT "simulacion_resultado_id_especie_fkey" FOREIGN KEY (id_especie) REFERENCES especies(id_especie) ON DELETE RESTRICT,
    CONSTRAINT "simulacion_resultado_id_pecera_fkey" FOREIGN KEY (id_pecera) REFERENCES peceras(id_pecera) ON DELETE RESTRICT,
    CONSTRAINT "ck_simulacion_resultado_percentiles" CHECK (mortalidad_p5_pct <= mortalidad_mediana_pct AND mortalidad_mediana_pct <= mortalidad_p95_pct),
    CONSTRAINT "simulacion_resultado_etiqueta_check" CHECK (etiqueta = 'NO_CALIBRADO'::text),
    CONSTRAINT "simulacion_resultado_horas_fuera_rango_check" CHECK (horas_fuera_rango >= 0::numeric),
    CONSTRAINT "simulacion_resultado_mortalidad_mediana_pct_check" CHECK (mortalidad_mediana_pct >= 0::numeric AND mortalidad_mediana_pct <= 100::numeric),
    CONSTRAINT "simulacion_resultado_mortalidad_p5_pct_check" CHECK (mortalidad_p5_pct >= 0::numeric AND mortalidad_p5_pct <= 100::numeric),
    CONSTRAINT "simulacion_resultado_mortalidad_p95_pct_check" CHECK (mortalidad_p95_pct >= 0::numeric AND mortalidad_p95_pct <= 100::numeric)
);

CREATE TABLE IF NOT EXISTS public."schema_migrations" (
    "version" text NOT NULL,
    "description" text NOT NULL,
    "applied_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "schema_migrations_pkey" PRIMARY KEY (version)
);

INSERT INTO public."schema_migrations" ("version", "description", "applied_at") VALUES
